"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["48237"],{93683(e){e.exports=JSON.parse('{"id":"V4-028","slug":"self-invested-personal-pension","term":"Self-Invested Personal Pension (SIPP)","also_known_as":[],"difficulty":"Intermediate","definition":"A Self-Invested Personal Pension (SIPP) is a type of personal pension in the United Kingdom that allows savers to choose and manage their own investments, with tax relief on contributions.","explanation":["A SIPP works like other personal pensions but gives the saver much wider control over investments, such as funds, shares, investment trusts, bonds and, in some cases, commercial property.","Contributions receive tax relief. For basic-rate taxpayers, the pension provider claims tax back from the government and adds it to the pension. For example, a personal contribution of 80 becomes 100 in the pension. Higher-rate taxpayers can claim additional relief through their tax return. Investments grow free of income tax and capital gains tax.","Money cannot usually be accessed until a minimum pension age, which is 55 and set to rise to 57 from 2028. At that point, part of the pension can usually be taken tax-free as a lump sum, and the rest is taxed as income when withdrawn.","SIPPs suit people who want control and are comfortable making investment decisions, or who use a financial adviser. Fees vary between providers. Annual limits apply to how much can be paid in with tax relief. SIPPs are similar in purpose to individual retirement accounts in the United States."],"note":"","total":1725,"prev":{"slug":"self-insurance","term":"Self-Insurance"},"next":{"slug":"seller-financing","term":"Seller Financing"}}')}}]);